#include <stdio.h>

int N, T, array[30]; // N won't be larger than 30

int groupSum(int len_covered, int partial_sum){
    if(partial_sum==0){
        return 1;
    }
    if(len_covered>=N){
        return 0;
    }
    int x=0;
    if(array[len_covered]<partial_sum){
        x= groupSum(++len_covered,partial_sum-array[len_covered]);
    }
    return groupSum(++len_covered,partial_sum)||x;
}

int main(){
	scanf("%d %d",&N,&T);
	for(int i=0;i<N;i++){
	    scanf("%d ",&array[i]);
	}
	printf("%s\n", groupSum(0, T)==1?"YES":"NO");
	return 0;
}

